// Bridges the bindings generated by `wrangler types` (Cloudflare.Env) to the
// CloudflareEnv name that @opennextjs/cloudflare's getCloudflareContext uses.
declare global {
  interface CloudflareEnv extends Cloudflare.Env {
    // Secrets set with `wrangler secret put`, so they are absent from the
    // generated bindings but present at runtime.
    CRON_SECRET?: string;
    TURNSTILE_SECRET?: string;
  }
}

export {};
